// ─── Normalizar Payload ────────────────────────────────────────────────
// Extrai e valida os campos do body, aplicando defaults seguros.
// O N8N nunca modifica estados — apenas lê o currentState da FSM.

const body = $input.item.json.body || $input.item.json;

// Campos obrigatórios
const sessionId     = body.sessionId || null;
const currentState  = body.currentState || 'UNKNOWN';
const area          = body.area || null;
const subarea       = body.subarea || null;
const message       = (body.message || '').trim();

// Campos opcionais
const dadosColetados = body.dadosColetados || {};
const documentos     = body.documentos || [];
const protocolo      = body.protocolo || null;

// Validação mínima
const erros = [];
if (!sessionId) erros.push('sessionId obrigatório');
if (!message)   erros.push('message obrigatório');
if (!area)      erros.push('area obrigatório');

if (erros.length > 0) {
  return [{ json: { _valido: false, erros, sessionId } }];
}

// Estados da FSM que chegam ao N8N (pós-coleta de dados básicos)
const ESTADOS_CONVERSACIONAIS = [
  'AWAITING_CASE_DESCRIPTION',
  'CASE_DESCRIPTION_COLLECTED',
  'AWAITING_DOCUMENT_UPLOAD_OPTION',
  'DOCUMENT_UPLOAD_OPTION_SELECTED',
  'DOCUMENTS_UPLOADED',
  'QUALIFICATION_COMPLETE',
  'READY_TO_CLOSE'
];

const ehEstadoConversacional = ESTADOS_CONVERSACIONAIS.includes(currentState);

return [{
  json: {
    _valido: true,
    sessionId,
    currentState,
    area,
    subarea: subarea || '',
    message,
    dadosColetados,
    documentos,
    protocolo,
    ehEstadoConversacional,
    temDocumentos: documentos.length > 0,
    qualificacaoCompleta: currentState === 'QUALIFICATION_COMPLETE' || currentState === 'READY_TO_CLOSE',
    timestamp: new Date().toISOString()
  }
}];

// ─── Construir / Mesclar Contexto ──────────────────────────────────────
// Mescla contexto salvo no Postgres com os dados da mensagem atual.
// Se não houver contexto salvo, inicializa um novo.

const payload = $('02 · Normalizar Payload').item.json;
const dbRows  = $input.all();

// Linha salva no banco (pode estar vazia se for a primeira mensagem)
const dbCtx = dbRows.length > 0 && dbRows[0].json?.session_id
  ? dbRows[0].json
  : null;

let historico = [];
let perguntasRespondidas = {};
let documentosSolicitados = [];
let turno = 1;
let resumoParcial = null;

if (dbCtx) {
  try { historico = JSON.parse(dbCtx.historico_mensagens || '[]'); } catch { historico = []; }
  try { perguntasRespondidas = JSON.parse(dbCtx.perguntas_respondidas || '{}'); } catch { perguntasRespondidas = {}; }
  try { documentosSolicitados = JSON.parse(dbCtx.documentos_solicitados || '[]'); } catch { documentosSolicitados = []; }
  turno = (dbCtx.turno || 0) + 1;
  resumoParcial = dbCtx.resumo_parcial || null;
}

// Adicionar a mensagem atual ao histórico
historico.push({
  turno,
  role: 'user',
  content: payload.message,
  timestamp: payload.timestamp,
  state: payload.currentState
});

// Limitar histórico a últimas 20 mensagens (evita tokens excessivos)
if (historico.length > 20) historico = historico.slice(-20);

// Montar histórico formatado para o prompt OpenAI
const historicoFormatado = historico
  .map(m => `[${m.role === 'user' ? 'CLIENTE' : 'AGENTE'}]: ${m.content}`)
  .join('\n');

return [{
  json: {
    ...payload,
    contexto: {
      sessionId:             payload.sessionId,
      area:                  payload.area,
      subarea:               payload.subarea,
      turno,
      historico,
      historicoFormatado,
      perguntasRespondidas,
      documentosSolicitados,
      resumoParcial,
      dadosColetados:        payload.dadosColetados,
      documentos:            payload.documentos,
      qualificacaoCompleta:  payload.qualificacaoCompleta,
      temDocumentos:         payload.temDocumentos
    }
  }
}];

// ─── Agente Previdenciário ─────────────────────────────────────────────
// Monta o system prompt especializado em Direito Previdenciário.
// Subáreas: BPC/LOAS, Aposentadoria, Auxílio-doença, Pensão, Revisão.

const ctx = $json.contexto;
const subarea = ctx.subarea;

const DOCUMENTOS_POR_SUBAREA = {
  'BPC/LOAS':       ['RG e CPF do requerente e responsável', 'Laudo médico atualizado (menos de 90 dias)', 'Comprovante CadÚnico', 'Comprovante de renda familiar'],
  'Aposentadoria':  ['CTPS física ou digital', 'Extrato do CNIS (Meu INSS)', 'Documentos de períodos especiais (se houver)', 'PPP — Perfil Profissiográfico Previdenciário'],
  'Auxílio-doença': ['Laudo médico atualizado (menos de 30 dias)', 'Exames complementares recentes', 'Atestado médico com CID', 'Extrato do CNIS'],
  'Pensão':         ['Certidão de óbito', 'RG e CPF do falecido e dependente', 'Documentos que comprovem dependência econômica', 'Certidão de casamento ou comprovante de união'],
  'Revisão':        ['Carta de concessão do benefício original', 'Número do NB (Número do Benefício)', 'Documentos do período a revisar', 'Extrato do CNIS']
};

const documentosSolicitados = DOCUMENTOS_POR_SUBAREA[subarea] || ['RG e CPF', 'Comprovante de residência', 'Documentos relacionados ao benefício'];

const systemPrompt = `Você é um assistente jurídico especializado em Direito Previdenciário do escritório Elilon Lopes Advogados.

Sua função é qualificar o atendimento do cliente, coletando informações essenciais de forma humanizada e empática.

Subárea atual: ${subarea || 'Previdenciário (geral)'}

REGRAS OBRIGATÓRIAS:
- Nunca prometa resultado, prazo ou valor
- Nunca emita parecer jurídico
- Use linguagem simples, acessível e acolhedora
- Faça no máximo 3 perguntas por mensagem
- Seja objetivo e direto
- Se o cliente já respondeu algo, não repita a pergunta

INFORMAÇÕES JÁ COLETADAS PELA FSM:
${JSON.stringify(ctx.dadosColetados, null, 2)}

HISTÓRICO DA CONVERSA:
${ctx.historicoFormatado || '(sem histórico anterior)'}

DOCUMENTOS NECESSÁRIOS PARA ESTA SUBÁREA:
${documentosSolicitados.map((d, i) => `${i + 1}. ${d}`).join('\n')}

Documentos já enviados pelo cliente: ${ctx.documentos.length} arquivo(s)

Responda APENAS com JSON válido (sem markdown):
{
  "resposta": "sua mensagem humanizada para o cliente (máx 3 perguntas)",
  "perguntas_feitas": ["lista das perguntas feitas nesta mensagem"],
  "documentos_solicitados": ["documentos pedidos nesta mensagem"],
  "informacoes_coletadas": {"chave": "valor"},
  "qualificacao_suficiente": false
}`;

return [{
  json: {
    ...($json),
    agente: {
      area: 'Previdenciário',
      subarea,
      systemPrompt,
      documentosSolicitados
    }
  }
}];

const ctx = $json.contexto;
const subarea = ctx.subarea;

const DOCUMENTOS_POR_SUBAREA = {
  'Rescisão':              ['CTPS física ou digital', 'Termo de Rescisão (TRCT)', 'Contracheques dos últimos 3 meses', 'Extrato do FGTS'],
  'FGTS':                  ['CTPS', 'Extrato do FGTS (Caixa Econômica)', 'Contracheques', 'Contrato de trabalho (se houver)'],
  'Horas Extras':          ['Cartão de ponto ou espelho de ponto', 'Contracheques dos últimos 6 meses', 'CTPS', 'Mensagens ou e-mails sobre jornada (se houver)'],
  'Assédio':               ['Print de mensagens ou e-mails (se houver)', 'Declaração de testemunhas (se houver)', 'Atestados ou laudos médicos', 'Boletim de Ocorrência (se houver)'],
  'Acidente de Trabalho':  ['CAT — Comunicação de Acidente de Trabalho', 'Laudo médico do acidente', 'CTPS', 'Boletim de Ocorrência (se houver)']
};

const documentosSolicitados = DOCUMENTOS_POR_SUBAREA[subarea] || ['CTPS', 'Contracheques', 'Documentos relacionados ao caso'];

const systemPrompt = `Você é um assistente jurídico especializado em Direito do Trabalho do escritório Elilon Lopes Advogados.

Subárea atual: ${subarea || 'Trabalhista (geral)'}

REGRAS OBRIGATÓRIAS:
- Nunca prometa resultado, prazo ou valor
- Nunca emita parecer jurídico
- Use linguagem simples, acessível e empática
- Faça no máximo 3 perguntas por mensagem
- Se o cliente já respondeu algo, não repita a pergunta

INFORMAÇÕES JÁ COLETADAS:
${JSON.stringify(ctx.dadosColetados, null, 2)}

HISTÓRICO:
${ctx.historicoFormatado || '(sem histórico)'}

DOCUMENTOS NECESSÁRIOS:
${documentosSolicitados.map((d, i) => `${i + 1}. ${d}`).join('\n')}

Documentos enviados: ${ctx.documentos.length} arquivo(s)

Responda APENAS com JSON válido:
{
  "resposta": "mensagem humanizada (máx 3 perguntas)",
  "perguntas_feitas": [],
  "documentos_solicitados": [],
  "informacoes_coletadas": {},
  "qualificacao_suficiente": false
}`;

return [{ json: { ...($json), agente: { area: 'Trabalhista', subarea, systemPrompt, documentosSolicitados } } }];

const ctx = $json.contexto;
const subarea = ctx.subarea;

const DOCUMENTOS_POR_SUBAREA = {
  'Impostos':                  ['CNPJ e Contrato Social', 'Guias de pagamento (DARF, DAS)', 'Declarações fiscais (IRPJ, SPED)', 'Auto de infração (se houver)'],
  'Planejamento Tributário':   ['Balanço patrimonial último exercício', 'DRE — Demonstração de Resultado', 'CNPJ e Contrato Social', 'Faturamento dos últimos 12 meses'],
  'Restituição':               ['CPF ou CNPJ', 'Declaração do exercício em questão', 'Comprovantes de pagamento indevido', 'Extrato de conta (para crédito da restituição)'],
  'Execução Fiscal':           ['CDA — Certidão de Dívida Ativa', 'CNPJ ou CPF', 'Documentos de bens (penhora)', 'Comprovantes de pagamento anteriores']
};

const documentosSolicitados = DOCUMENTOS_POR_SUBAREA[subarea] || ['CNPJ ou CPF', 'Documentação fiscal pertinente'];

const systemPrompt = `Você é um assistente jurídico especializado em Direito Tributário do escritório Elilon Lopes Advogados.

Subárea atual: ${subarea || 'Tributário (geral)'}

REGRAS OBRIGATÓRIAS:
- Nunca prometa resultado, prazo ou valor
- Nunca emita parecer jurídico
- Use linguagem simples e técnica apenas quando necessário
- Faça no máximo 3 perguntas por mensagem

INFORMAÇÕES JÁ COLETADAS:
${JSON.stringify(ctx.dadosColetados, null, 2)}

HISTÓRICO:
${ctx.historicoFormatado || '(sem histórico)'}

DOCUMENTOS NECESSÁRIOS:
${documentosSolicitados.map((d, i) => `${i + 1}. ${d}`).join('\n')}

Documentos enviados: ${ctx.documentos.length} arquivo(s)

Responda APENAS com JSON válido:
{
  "resposta": "mensagem humanizada (máx 3 perguntas)",
  "perguntas_feitas": [],
  "documentos_solicitados": [],
  "informacoes_coletadas": {},
  "qualificacao_suficiente": false
}`;

return [{ json: { ...($json), agente: { area: 'Tributário', subarea, systemPrompt, documentosSolicitados } } }];

const ctx = $json.contexto;
const subarea = ctx.subarea;

const DOCUMENTOS_POR_SUBAREA = {
  'Contratos':    ['Contrato assinado e rubricado', 'Comprovantes de pagamento', 'Comunicações sobre o descumprimento', 'Nota fiscal ou recibo (se houver)'],
  'Consumidor':   ['Nota fiscal ou comprovante de compra', 'Print do SAC ou protocolo Procon', 'Foto ou documentação do defeito/problema', 'RG e CPF'],
  'Família':      ['RG e CPF de todos os envolvidos', 'Certidão de casamento (ou nascimento para guarda)', 'Documentos de bens (se partilha)', 'Comprovante de renda (se alimentos)'],
  'Indenização':  ['Boletim de Ocorrência (se houver)', 'Laudos médicos ou periciais', 'Documentação do dano (fotos, notas fiscais)', 'Dados do responsável pelo dano']
};

const documentosSolicitados = DOCUMENTOS_POR_SUBAREA[subarea] || ['RG e CPF', 'Documentação relacionada ao caso'];

const systemPrompt = `Você é um assistente jurídico especializado em Direito Civil do escritório Elilon Lopes Advogados.

Subárea atual: ${subarea || 'Cível (geral)'}

REGRAS OBRIGATÓRIAS:
- Nunca prometa resultado, prazo ou valor
- Nunca emita parecer jurídico
- Use linguagem acessível e empática
- Faça no máximo 3 perguntas por mensagem

INFORMAÇÕES JÁ COLETADAS:
${JSON.stringify(ctx.dadosColetados, null, 2)}

HISTÓRICO:
${ctx.historicoFormatado || '(sem histórico)'}

DOCUMENTOS NECESSÁRIOS:
${documentosSolicitados.map((d, i) => `${i + 1}. ${d}`).join('\n')}

Documentos enviados: ${ctx.documentos.length} arquivo(s)

Responda APENAS com JSON válido:
{
  "resposta": "mensagem humanizada (máx 3 perguntas)",
  "perguntas_feitas": [],
  "documentos_solicitados": [],
  "informacoes_coletadas": {},
  "qualificacao_suficiente": false
}`;

return [{ json: { ...($json), agente: { area: 'Cível', subarea, systemPrompt, documentosSolicitados } } }];

// ─── Chamada OpenAI via HTTP ─────────────────────────────────────────────
// Usa httpRequest interno ao Code node via $helpers — compatível com
// N8N Community Edition sem instalar nodes langchain.
// O agente já montou systemPrompt no node anterior.

const ctx   = $json.contexto;
const agente = $json.agente;

// Mensagens para o modelo
const mensagens = [
  { role: 'system', content: agente.systemPrompt },
  { role: 'user',   content: ctx.message || $json.message }
];

// Resposta de fallback (se OpenAI falhar)
const fallbackResposta = {
  resposta: 'Entendi sua situação. Para darmos continuidade ao seu atendimento, preciso confirmar algumas informações. Você pode me descrever melhor o que aconteceu?',
  perguntas_feitas: [],
  documentos_solicitados: agente.documentosSolicitados.slice(0, 2),
  informacoes_coletadas: {},
  qualificacao_suficiente: false
};

let analiseIA = fallbackResposta;

try {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) throw new Error('OPENAI_API_KEY não configurada');

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/chat/completions',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: 'gpt-4o-mini',
      messages: mensagens,
      temperature: 0.4,
      max_tokens: 800,
      response_format: { type: 'json_object' }
    }),
    returnFullResponse: false
  });

  const content = response?.choices?.[0]?.message?.content || '{}';
  analiseIA = JSON.parse(content);

  // Garantir campos obrigatórios
  if (!analiseIA.resposta) analiseIA.resposta = fallbackResposta.resposta;
  if (!Array.isArray(analiseIA.perguntas_feitas)) analiseIA.perguntas_feitas = [];
  if (!Array.isArray(analiseIA.documentos_solicitados)) analiseIA.documentos_solicitados = [];
  if (!analiseIA.informacoes_coletadas) analiseIA.informacoes_coletadas = {};

} catch (e) {
  console.error('[N8N OpenAI] Falha:', e.message);
  analiseIA = fallbackResposta;
}

return [{
  json: {
    ...($json),
    analiseIA,
    openai_ok: analiseIA !== fallbackResposta
  }
}];

// ─── Montar Resposta para o ChatWidget ───────────────────────────────────
// A FSM recebe este objeto e exibe a resposta como mensagem do BOT.
// A FSM decide se avança de estado ou não — o N8N não interfere.

const analise = $json.analiseIA;
const ctx     = $json.contexto;

return [{
  json: {
    sucesso: true,
    sessionId: $json.sessionId,
    resposta: analise.resposta,
    proximaAcao: 'CONTINUAR_COLETA',
    perguntasAdicionais: analise.perguntas_feitas || [],
    documentosSolicitados: analise.documentos_solicitados || [],
    informacoesColetadas: analise.informacoes_coletadas || {},
    qualificacaoSuficiente: analise.qualificacao_suficiente || false,
    turno: ctx.turno,
    _meta: {
      area: ctx.area,
      subarea: ctx.subarea,
      openai_ok: $json.openai_ok
    }
  }
}];

// ─── Gerar Resumo Executivo Final ────────────────────────────────────────
// Executado quando qualificacaoCompleta = true.
// Consolida todos os dados para persistência e encaminhamento.

const ctx  = $json.contexto;
const body = $json;

const dados = ctx.dadosColetados || {};

// Consolidar tudo que foi coletado ao longo da conversa
const resumo = {
  protocolo:    body.protocolo || null,
  gerado_em:    new Date().toISOString(),

  cliente: {
    nome:      dados.nome     || dados.name || '',
    telefone:  dados.telefone || dados.phone || '',
    email:     dados.email    || '',
    cidade:    dados.cidade   || dados.city || '',
    estado:    dados.estado   || dados.state || ''
  },

  juridico: {
    area:          ctx.area,
    subarea:       ctx.subarea,
    descricao_caso: dados.descricaoCaso || dados.descricao || body.message || ''
  },

  qualificacao: {
    historico_turnos: ctx.historico.length,
    informacoes_extras: ctx.perguntasRespondidas,
    documentos_solicitados: ctx.documentosSolicitados
  },

  documentos: {
    count: ctx.documentos.length,
    lista: ctx.documentos.map(d => ({
      nome: d.original_name || d.nome || d.fileName || '',
      tipo: d.mime_type     || d.tipo || '',
      tam:  d.file_size     || d.size || 0
    }))
  },

  resumo_narrativo: [
    `Cliente ${dados.nome || 'não identificado'} (${dados.cidade || ''}/${dados.estado || ''})`,
    `Área: ${ctx.area} — Subárea: ${ctx.subarea}`,
    `Descrição: ${(dados.descricaoCaso || '').slice(0, 300)}`,
    `Documentos enviados: ${ctx.documentos.length}`,
    `Turnos de conversa: ${ctx.historico.length}`
  ].join('. ')
};

return [{
  json: {
    ...body,
    resumo,
    _etapa: 'ENCERRAMENTO'
  }
}];

// ─── Montar Mensagem de Confirmação ──────────────────────────────────────
// Gera a mensagem de confirmação que o ChatWidget exibirá ao cliente.
// O cliente confirma via FSM — o N8N apenas prepara o texto.

const resumo = $json.resumo;
const cli    = resumo.cliente;
const jur    = resumo.juridico;
const docs   = resumo.documentos;

const textoConfirmacao = [
  '📋 *Revisão das Informações*',
  '',
  `👤 *Nome:* ${cli.nome || 'Não informado'}`,
  `📞 *Telefone:* ${cli.telefone || 'Não informado'}`,
  `✉️ *E-mail:* ${cli.email || 'Não informado'}`,
  `📍 *Cidade/Estado:* ${cli.cidade || ''}/${cli.estado || ''}`,
  '',
  `⚖️ *Área Jurídica:* ${jur.area}`,
  `🔖 *Subárea:* ${jur.subarea}`,
  '',
  `📁 *Documentos enviados:* ${docs.count} arquivo(s)`,
  '',
  '---',
  '*Está tudo correto?*',
  'Confirme para finalizar seu atendimento ou solicite alteração.'
].join('\n');

return [{
  json: {
    ...($json),
    confirmacao: {
      mensagem: textoConfirmacao,
      dados: resumo
    }
  }
}];

// ─── Encerrar Atendimento ────────────────────────────────────────────────
// Monta a resposta final para a FSM.
// A FSM exibe a mensagem de encerramento e transiciona para CLOSED.

const resumo = $json.resumo;
const cli    = resumo?.cliente || {};

const mensagemFinal = [
  `✅ *Atendimento registrado com sucesso!*`,
  '',
  resumo?.protocolo
    ? `📌 *Protocolo:* ${resumo.protocolo}`
    : '📌 Protocolo será gerado em instantes.',
  '',
  `Nossa equipe jurídica analisará seu caso e entrará em contato em breve.`,
  '',
  `📞 Se preferir, ligue: **(11) 0000-0000**`,
  `✉️ Ou envie e-mail: **contato@elilon.com.br**`
].join('\n');

return [{
  json: {
    sucesso: true,
    sessionId: $json.sessionId,
    resposta: mensagemFinal,
    proximaAcao: 'ENCERRAR',
    protocolo: resumo?.protocolo || null,
    resumo_final: resumo,
    _meta: {
      workflow: 'chat-juridico-conversacional-v1',
      sprint: '4.0.1',
      etapa: 'encerramento'
    }
  }
}];

parameters.query:
CREATE TABLE IF NOT EXISTS n8n_chat_contexto (
  session_id             TEXT        PRIMARY KEY,
  area                   TEXT,
  subarea                TEXT,
  historico_mensagens    JSONB       DEFAULT '[]',
  perguntas_respondidas  JSONB       DEFAULT '{}',
  documentos_solicitados JSONB       DEFAULT '[]',
  resumo_parcial         TEXT,
  turno                  INTEGER     DEFAULT 1,
  criado_em              TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
  atualizado_em          TIMESTAMP   DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_n8n_chat_contexto_session_id ON n8n_chat_contexto (session_id);
CREATE INDEX IF NOT EXISTS idx_n8n_chat_contexto_area      ON n8n_chat_contexto (area);

SELECT 'n8n_chat_contexto OK' AS status;
